Indicator: 60 Min 20 Bar EMA (TradeStation)
             Inputs:
                _length( 20) ,
                  SessionEndTime( 1315 {PST US Session}) ;
             If CurrentBar - 240 Then valuel = Xaverage( C , 240 ) ;
             If CurrentBar > 240 Then
             Begin
                   If FracPortion(( Time - 30) / 100) = 0 or Time -  SessionEndTime Then
                  Begin
                       valuel = valuel[l] + (2 / (_length+ 1 )) * ( C - valuel[l] ) ;
                       value2 = valuel ;
                        Plotl( valuel , " 60 min EMA" );
                  End
                  Else
                  Begin
                       value2 = valuel + (2 / (_length+ 1 )) * ( C - valuel[l]) ;
                        Plotl ( value2 , " 60 min EMA" ) ;
                  End ;
             End ;
             Note:   Adjust 1315 to match session end time for your time zone. 1315 is for Pacific Standard Time.

Indicator: 15 Min 20 Bar EMA (TradeStation)
             Inputs:
                _length( 20);
             If CurrentBar - 60 Then valuel - Xaverage( C, 60 ) ;
             If CurrentBar > 60 Then
             Begin
                  If FracPortion( Time I 15 ) - 0 Then
                  Begin
                      valuel = valuel[l] + (2 / (_length+ 1 )) * ( C - valuel[l] ) ;
                      value2 = valuel;
                       Plotl( valuel, "15 min EMA");
                  End
                  Else
                  Begin
                      value2 = valuel + ( 2 / (_length+ 1 )) * ( C - valuel[l] ) ;
                       Plotl( value2, "15 min EMA");
                  End;
             End;
